-- Additive, transactional CMS migration. Never run DROP TABLE/TRUNCATE or replace editorial rows.
begin;
create table if not exists public.content_migrations (key text primary key, applied_at timestamptz not null default now());
create table if not exists public.media_assets (
 id uuid primary key default gen_random_uuid(), storage_path text not null unique, url text not null,
 mime_type text not null, byte_size integer not null check(byte_size between 1 and 6291456),
 original_name text not null default '', alt_text text not null default '', credit text not null default '',
 created_at timestamptz not null default now(), deleted_at timestamptz
);
create table if not exists public.authors (
 id uuid primary key default gen_random_uuid(), slug text not null unique, legacy_key text unique,
 name_en text not null default '', name_ckb text not null default '', name_kmr text not null default '',
 title_en text not null default '', title_ckb text not null default '', title_kmr text not null default '',
 position_en text not null default '', position_ckb text not null default '', position_kmr text not null default '',
 summary_en text not null default '', summary_ckb text not null default '', summary_kmr text not null default '',
 biography_en text not null default '', biography_ckb text not null default '', biography_kmr text not null default '',
 history_en text not null default '', history_ckb text not null default '', history_kmr text not null default '',
 contributions_en text not null default '', contributions_ckb text not null default '', contributions_kmr text not null default '',
 writings_intro_en text not null default '', writings_intro_ckb text not null default '', writings_intro_kmr text not null default '',
 feast_en text not null default '', feast_ckb text not null default '', feast_kmr text not null default '',
 life_dates_en text not null default '', life_dates_ckb text not null default '', life_dates_kmr text not null default '',
 birth_info text not null default '', death_info text not null default '', aliases text[] not null default '{}',
 kind text not null default 'saint' check(kind in ('saint','father','saint-and-father')),
 icon_url text not null default '', icon_media_id uuid references public.media_assets(id) on delete restrict,
 icon_alt text not null default '', icon_credit text not null default '', icon_source text not null default '', icon_license_url text not null default '',
 source_reference text not null default '', source_url text not null default '',
 sort_order integer not null default 0, published boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
alter table public.quotes add column if not exists author_id uuid references public.authors(id) on delete restrict;
alter table public.quotes add column if not exists text_en text;
alter table public.quotes add column if not exists updated_at timestamptz not null default now();
alter table public.quotes add column if not exists deleted_at timestamptz;
alter table public.quotes add column if not exists legacy_key text;
create unique index if not exists quotes_legacy_key on public.quotes(legacy_key) where legacy_key is not null;
-- Empty untranslated fields are valid; publishing validation happens at the API boundary.
alter table public.quotes drop constraint if exists quotes_text_ckb_check;
alter table public.quotes drop constraint if exists quotes_text_kmr_check;
alter table public.quotes drop constraint if exists quotes_father_check;
alter table public.prayers add column if not exists text_en text;
alter table public.prayers add column if not exists title_en text;
alter table public.prayers add column if not exists updated_at timestamptz not null default now();
alter table public.prayers add column if not exists deleted_at timestamptz;
alter table public.prayers drop constraint if exists prayers_title_ckb_check;
alter table public.prayers drop constraint if exists prayers_title_kmr_check;
alter table public.prayers drop constraint if exists prayers_text_ckb_check;
alter table public.prayers drop constraint if exists prayers_text_kmr_check;
alter table public.sources add column if not exists content_ckb text;
alter table public.sources add column if not exists content_kmr text;
alter table public.sources add column if not exists updated_at timestamptz not null default now();
alter table public.sources add column if not exists deleted_at timestamptz;
create table if not exists public.writings (
 id uuid primary key default gen_random_uuid(), author_id uuid not null references public.authors(id) on delete restrict,
 title_en text not null default '', title_ckb text not null default '', title_kmr text not null default '',
 subtitle_en text not null default '', subtitle_ckb text not null default '', subtitle_kmr text not null default '',
 body_en text not null default '', body_ckb text not null default '', body_kmr text not null default '',
 reference text not null default '', source_url text not null default '', sort_order integer not null default 0,
 published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table if not exists public.doctrines (
 id uuid primary key default gen_random_uuid(), slug text not null unique, legacy_key text unique,
 category text not null default 'doctrine' check(category in ('doctrine','council')), council_year text not null default '',
 title_en text not null default '', title_ckb text not null default '', title_kmr text not null default '',
 subtitle_en text not null default '', subtitle_ckb text not null default '', subtitle_kmr text not null default '',
 body_en text not null default '', body_ckb text not null default '', body_kmr text not null default '',
 bible_references text not null default '', father_references text not null default '', council_references text not null default '',
 reference text not null default '', source_url text not null default '', icon_url text not null default '',
 icon_media_id uuid references public.media_assets(id) on delete restrict, icon_alt text not null default '', icon_credit text not null default '',
 sort_order integer not null default 0, published boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table if not exists public.doctrine_authors (
 doctrine_id uuid not null references public.doctrines(id) on delete cascade,
 author_id uuid not null references public.authors(id) on delete restrict,
 primary key(doctrine_id,author_id)
);
create table if not exists public.bible_explanations (
 id uuid primary key default gen_random_uuid(), author_id uuid not null references public.authors(id) on delete restrict,
 book text not null check(book ~ '^[A-Z0-9]{3}$'), chapter integer not null check(chapter between 1 and 151),
 verse_start integer not null check(verse_start between 1 and 200), verse_end integer not null check(verse_end between verse_start and 200),
 title_en text not null default '', title_ckb text not null default '', title_kmr text not null default '',
 body_en text not null default '', body_ckb text not null default '', body_kmr text not null default '',
 reference text not null default '', source_url text not null default '',
 sort_order integer not null default 0, published boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table if not exists public.bible_editions (
 id text primary key, title_en text not null default '', title_ckb text not null default '', title_kmr text not null default '',
 description_en text not null default '', description_ckb text not null default '', description_kmr text not null default '',
 sort_order integer not null default 0, published boolean not null default true,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
-- Overrides are explicit, separately stored editorial revisions. Licensed source text stays intact.
create table if not exists public.bible_overrides (
 id uuid primary key default gen_random_uuid(), edition_id text not null references public.bible_editions(id) on delete restrict,
 book text not null check(book ~ '^[A-Z0-9]{3}$'), chapter integer not null check(chapter between 1 and 151),
 verse integer not null check(verse between 1 and 200), text text not null default '', editorial_note text not null default '',
 published boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create unique index if not exists bible_overrides_active_passage on public.bible_overrides(edition_id,book,chapter,verse) where deleted_at is null;
create table if not exists public.daily_verses (
 id uuid primary key default gen_random_uuid(), date date not null, edition_id text not null references public.bible_editions(id) on delete restrict,
 book text not null check(book ~ '^[A-Z0-9]{3}$'), chapter integer not null check(chapter between 1 and 151),
 verse_start integer not null check(verse_start between 1 and 200), verse_end integer not null check(verse_end between verse_start and 200),
 text text not null default '', reference text not null default '', published boolean not null default false,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create unique index if not exists daily_verses_active_day on public.daily_verses(date,edition_id) where deleted_at is null;
create table if not exists public.content_blocks (
 id uuid primary key default gen_random_uuid(), key text not null unique, section text not null default 'general',
 text_en text not null default '', text_ckb text not null default '', text_kmr text not null default '',
 value_type text not null default 'text' check(value_type in ('text','image','visibility')),
 published boolean not null default false, sort_order integer not null default 0,
 created_at timestamptz not null default now(), updated_at timestamptz not null default now(), deleted_at timestamptz
);
create table if not exists public.editorial_revisions (
 id bigint generated always as identity primary key, table_name text not null, record_id text not null,
 operation text not null, previous_row jsonb, next_row jsonb, actor_id text, created_at timestamptz not null default now()
);
-- Record an immutable baseline of original editorial rows, including drafts.
do $$ declare t text; begin
 if not exists(select 1 from public.content_migrations where key='editorial-cms-v1') then
 foreach t in array array['quotes','prayers','sources'] loop
 execute format('insert into public.editorial_revisions(table_name,record_id,operation,previous_row,next_row) select %L,id::text,''MIGRATION_BASELINE'',to_jsonb(r),to_jsonb(r) from public.%I r',t,t);
 end loop; end if;
end $$;
create or replace function public.editorial_timestamp() returns trigger language plpgsql set search_path=public as $$
begin new.updated_at = clock_timestamp(); return new; end $$;
create or replace function public.record_editorial_revision() returns trigger language plpgsql security definer set search_path=public as $$
begin
 values(tg_table_name,coalesce(new.id::text,old.id::text),tg_op,case when tg_op='INSERT' then null else to_jsonb(old) end,case when tg_op='DELETE' then null else to_jsonb(new) end);
 return coalesce(new,old);
end $$;
-- Restricted server-only tables: no anonymous/direct authenticated editing.
do $$ declare t text; begin
 foreach t in array array['authors','writings','doctrines','bible_explanations','bible_editions','bible_overrides','daily_verses','content_blocks','quotes','prayers','sources'] loop
 execute format('drop trigger if exists editorial_timestamp on public.%I',t);
 execute format('create trigger editorial_timestamp before update on public.%I for each row execute function public.editorial_timestamp()',t);
 execute format('drop trigger if exists editorial_history on public.%I',t);
 execute format('create trigger editorial_history after insert or update or delete on public.%I for each row execute function public.record_editorial_revision()',t);
 end loop;
 foreach t in array array['authors','writings','doctrines','doctrine_authors','bible_explanations','bible_editions','bible_overrides','daily_verses','content_blocks','media_assets','editorial_revisions','content_migrations'] loop
 execute format('alter table public.%I enable row level security',t);
 execute format('revoke all on public.%I from anon, authenticated',t);
 execute format('grant all on public.%I to service_role',t);
 end loop;
end $$;
revoke all on function public.record_editorial_revision() from public,anon,authenticated;
revoke all on function public.editorial_timestamp() from public,anon,authenticated;
grant usage,select on sequence public.editorial_revisions_id_seq to service_role;
create index if not exists quotes_author_published on public.quotes(author_id,published) where deleted_at is null;
create index if not exists writings_author_published on public.writings(author_id,published) where deleted_at is null;
create index if not exists explanations_passage on public.bible_explanations(book,chapter,verse_start,verse_end) where deleted_at is null and published;
create index if not exists authors_order on public.authors(sort_order,name_en) where deleted_at is null;
create or replace view public.author_public_stats with (security_invoker=true) as
 select a.*,
 (select count(*)::integer from public.quotes q where q.author_id=a.id and q.published and q.deleted_at is null) as quote_count,
 (select count(*)::integer from public.writings w where w.author_id=a.id and w.published and w.deleted_at is null) as writing_count
 from public.authors a where a.published and a.deleted_at is null;
revoke all on public.author_public_stats from anon,authenticated;
grant select on public.author_public_stats to service_role;
-- Atomically save doctrine-to-author relationships; protected by server owner middleware.
create or replace function public.set_doctrine_authors(p_doctrine uuid,p_authors uuid[]) returns void language plpgsql security invoker set search_path=public as $$
begin
 if exists(select 1 from unnest(p_authors) x where not exists(select 1 from public.authors where id=x and deleted_at is null)) then raise exception 'Author not found' using errcode='23503'; end if;
 delete from public.doctrine_authors where doctrine_id=p_doctrine;
end $$;
revoke all on function public.set_doctrine_authors(uuid,uuid[]) from public,anon,authenticated;
grant execute on function public.set_doctrine_authors(uuid,uuid[]) to service_role;
-- Media files are public icons; all uploads and metadata writes still require owner authentication.
 values('editorial-media','editorial-media',true,6291456,array['image/png','image/jpeg','image/webp','image/avif']) on conflict(id) do nothing;
-- Seed statements are appended below, before COMMIT. IDs and conflict guards make them rerunnable.
create or replace view public.public_quote_topics with (security_invoker=true) as select distinct q.topic from public.quotes q join public.authors a on a.id=q.author_id where q.published and q.deleted_at is null and a.published and a.deleted_at is null;
create or replace view public.public_prayer_topics with (security_invoker=true) as select distinct topic from public.prayers where published and deleted_at is null;
revoke all on public.public_quote_topics,public.public_prayer_topics from anon,authenticated;
grant select on public.public_quote_topics,public.public_prayer_topics to service_role;
-- Full FK indexes also cover archived rows during integrity checks.
create index if not exists quotes_author_fk on public.quotes(author_id);
create index if not exists writings_author_fk on public.writings(author_id);
create index if not exists explanations_author_fk on public.bible_explanations(author_id);
create index if not exists doctrine_authors_author_fk on public.doctrine_authors(author_id);
create index if not exists authors_icon_media_fk on public.authors(icon_media_id);
create index if not exists doctrines_icon_media_fk on public.doctrines(icon_media_id);
create index if not exists overrides_edition_fk on public.bible_overrides(edition_id);
create index if not exists daily_edition_fk on public.daily_verses(edition_id);
-- GENERATED EDITORIAL IMPORT: original source-file wording; insert-only, never an update.
create or replace function public.save_doctrine_article(p_row jsonb,p_authors uuid[],p_id uuid default null,p_expected timestamptz default null) returns jsonb language plpgsql security invoker set search_path=public as $$
declare r public.doctrines; saved public.doctrines;
begin
 r=jsonb_populate_record(null::public.doctrines,p_row);
 if p_id is null then
 else
 update public.doctrines set (slug,category,council_year,title_en,title_ckb,title_kmr,subtitle_en,subtitle_ckb,subtitle_kmr,body_en,body_ckb,body_kmr,reference,source_url,bible_references,father_references,council_references,icon_url,icon_media_id,icon_alt,icon_credit,sort_order,published)=(r.slug,r.category,r.council_year,r.title_en,r.title_ckb,r.title_kmr,r.subtitle_en,r.subtitle_ckb,r.subtitle_kmr,r.body_en,r.body_ckb,r.body_kmr,r.reference,r.source_url,r.bible_references,r.father_references,r.council_references,r.icon_url,r.icon_media_id,r.icon_alt,r.icon_credit,r.sort_order,r.published) where id=p_id and deleted_at is null and (p_expected is null or updated_at=p_expected) returning * into saved;
 if not found then return null; end if;
 end if;
 perform public.set_doctrine_authors(saved.id,p_authors);
 return to_jsonb(saved);
end $$;
revoke all on function public.save_doctrine_article(jsonb,uuid[],uuid,timestamptz) from public,anon,authenticated;
grant execute on function public.save_doctrine_article(jsonb,uuid[],uuid,timestamptz) to service_role;
Feast calendar: https://www.oca.org/saints/lives/1134/01/28/100333-saint-isaac-the-syrian-bishop-of-nineveh','7th century · exact dates uncertain','7th century · exact dates uncertain','Isaac came from the region of present-day Qatar in the seventh century. He served briefly as bishop of Nineveh before returning to solitude. His ascetical homilies passed from Syriac into Greek and became treasured reading in Orthodox monastic life. Exact birth and death dates are uncertain.','ئیسحاق لە سەدەی حەوتەمدا لە ناوچەی قەتەری ئەمڕۆ هات. ماوەیەکی کورت ئەسقوفی نەینەوا بوو و پاشان گەڕایەوە بۆ ژیانی تەنیایی. وتارە زاهدانەکانی لە سووریانییەوە وەرگێڕدران بۆ یۆنانی و بوون بە خوێندنەوەیەکی بەهادار لە ڕاهیبایەتیی ئۆرتۆدۆکسدا. ڕێکەوتی وردی لەدایکبوون و مردنی دیار نییە.','The seventh-century Syriac ascetic tradition. Some older calendar summaries give inconsistent dates; exact years are not asserted here.','نەریتی زاهدانەی سووریانی لە سەدەی حەوتەمدا. هەندێک کورتەی کۆنی ڕۆژژمێر ڕێکەوتی جیاواز دەدەن؛ لێرە ساڵی ورد بە دڵنیایی دیاری ناکرێت.','Teachings on repentance, stillness, humility, and mercy received widely in Orthodox spirituality.','فێرکردنی تۆبە، بێدەنگیی ناوەوە، خاکەڕایی و بەزەیی کە لە ژیانی ڕۆحیی ئۆرتۆدۆکسدا پێشوازیی فراوانیان لێکراوە.','The Ascetical Homilies. Homily numbering varies between editions; the quotation cites a specified edition.','وتارە زاهدانەکان. ژمارەی وتارەکان لە چاپە جیاوازەکاندا دەگۆڕێت؛ بۆ وتەکە چاپەکە دیاری کراوە.','28 January (OCA calendar)','٢٨ی کانوونی دووەم (ڕۆژژمێری OCA)','Isaac came from the region of present-day Qatar in the seventh century.','ئیسحاق لە سەدەی حەوتەمدا لە ناوچەی قەتەری ئەمڕۆ هات.') on conflict do nothing;
-- Match existing quotations only through exact normalized names/aliases. Never guess an attribution.
create or replace function public.editorial_name_key(value text) returns text language sql immutable strict set search_path=public as $$ select regexp_replace(lower(translate(value,'كيى','کیی')),'[[:space:][:punct:]]','','g') $$;
with aliases as (select a.id,public.editorial_name_key(n) as name_key from public.authors a cross join lateral unnest(array[a.name_en,a.name_ckb,a.name_kmr]||a.aliases) n where a.deleted_at is null and n<>''), matches as (select name_key,min(id::text)::uuid as id from aliases group by name_key having count(distinct id)=1)
update public.quotes q set author_id=m.id from matches m where q.author_id is null and public.editorial_name_key(q.father)=m.name_key;
-- Preserve unknown legacy names as minimal editable profiles, without invented biographies.
with names as(select public.editorial_name_key(father) as name_key,min(father) as name,bool_or(published and deleted_at is null) as published from public.quotes where author_id is null group by public.editorial_name_key(father))
 select 'legacy-'||md5(name_key),'legacy-quote-author:'||name_key,name,name,name,published,'father' from names on conflict do nothing;
update public.quotes q set author_id=a.id from public.authors a where q.author_id is null and a.legacy_key='legacy-quote-author:'||public.editorial_name_key(q.father);
alter table public.quotes alter column author_id set not null;
