 insert into public.doctrines (slug,category,council_year,title_en,title_ckb,title_kmr,subtitle_en,subtitle_ckb,subtitle_kmr,body_en,body_ckb,body_kmr,reference,source_url,bible_references,father_references,council_references,icon_url,icon_media_id,icon_alt,icon_credit,sort_order,published) values (r.slug,r.category,r.council_year,r.title_en,r.title_ckb,r.title_kmr,r.subtitle_en,r.subtitle_ckb,r.subtitle_kmr,r.body_en,r.body_ckb,r.body_kmr,r.reference,r.source_url,r.bible_references,r.father_references,r.council_references,r.icon_url,r.icon_media_id,r.icon_alt,r.icon_credit,r.sort_order,r.published) returning * into saved;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('92878037-5910-4931-8e41-16396d98a1e7','chrysostom','static-saint:chrysostom','Saint John Chrysostom','پایەپیرۆز یۆحەنای دەمزێڕین','','Chrysostom','','Archbishop of Constantinople','سەرئەسقوفی قسطنطینیە',array['پایەپیرۆز یۆحەنای دەمزێرین','Golden-Mouth','Golden Mouth','Chrysostomos','John Chrysostom','St. John Chrysostom','یۆحەنای دەمزێڕین']::text[],'saint-and-father',0,true,'/icons/chrysostom.webp','Saint John Chrysostom — Orthodox icon','Novgorod school · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Novgorod_School_-_John_Chrysostom_-_NG.M.01522_-_National_Museum_of_Art,_Architecture_and_Design.jpg','','https://www.oca.org/saints/lives/2018/11/13/103292-saint-john-chrysostom-archbishop-of-constantinople','https://www.oca.org/saints/lives/2018/11/13/103292-saint-john-chrysostom-archbishop-of-constantinople','c. 347–407','c. 347–407','Born in Antioch, John trained in rhetoric before embracing ascetic life. As a priest he explained Scripture to ordinary Christians; as archbishop of Constantinople he challenged luxury and cared for the poor. Conflict with powerful opponents brought exile. He died in 407 while being moved under guard.','لە ئەنتاکیا لەدایک بوو و پێش ژیانی زاهدانە، ڕەوانبێژی خوێند. وەک قەشە کتێبی پیرۆزی بۆ خەڵک ڕوون دەکردەوە. وەک سەرئەسقوفی قسطنطینیە داکۆکی لە هەژاران دەکرد و ڕەخنەی لە ژیانی پڕزێدەڕۆیی دەگرت. دوورخرایەوە و لە ساڵی ٤٠٧ لە کاتی گواستنەوەدا کۆچی دوایی کرد.','Antioch and Constantinople in the late fourth and early fifth centuries; the Church was developing its public life within the Roman Empire.','لە کۆتایی سەدەی چوارەم و سەرەتای پێنجەمدا لە ئەنتاکیا و قسطنطینیە ژیا؛ کاتێک کڵێسا ژیانی گشتی خۆی لە ناو ئیمپراتۆریەتی ڕۆماندا پەرە پێدەدا.','Biblical preaching, care for the poor, and pastoral reform. The Byzantine Divine Liturgy bearing his name preserves his liturgical legacy.','ڕاگەیاندنی کتێبی پیرۆز، خزمەتی هەژاران و چاکسازیی شوانایەتی. لیتورژیای بیزەنتی کە ناوی ئەوی هەڵگرتووە، میراتە لیتورژییەکەی دەپارێزێت.','Homilies on Matthew; Homilies on Romans; On the Priesthood.','وتارەکان لەسەر مەتا؛ وتارەکان لەسەر ڕۆمییەکان؛ دەربارەی کەهانەت.','13 November','١٣ی تشرینی دووەم','Born in Antioch, John trained in rhetoric before embracing ascetic life.','لە ئەنتاکیا لەدایک بوو و پێش ژیانی زاهدانە، ڕەوانبێژی خوێند.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('61275f6a-fe83-4d93-85b8-bd9b1727d57d','basil','static-saint:basil','Saint Basil the Great','پایەپیرۆز باسیلیۆسی مەزن','','the Great','','Bishop of Caesarea in Cappadocia','ئەسقوفی قیصەریەی کەپەدۆکیا',array['Basil of Caesarea','Basil the Great','St. Basil']::text[],'saint-and-father',1,true,'/icons/basil.webp','Saint Basil the Great — Orthodox icon','Novgorod school · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Novgorod_School_-_Saint_Basil_the_Great_-_NG.M.01523_-_National_Museum_of_Art,_Architecture_and_Design.jpg','','https://www.oca.org/saints/lives/2022/01/01/100003-saint-basil-the-great-archbishop-of-caesarea-in-cappadocia','https://www.oca.org/saints/lives/2022/01/01/100003-saint-basil-the-great-archbishop-of-caesarea-in-cappadocia','c. 330–379','c. 330–379','Basil became bishop of Caesarea in Cappadocia in 370. He joined theological learning to practical care: organizing relief for the sick and poor and guiding communities of monks. With the other Cappadocian Fathers he defended the Nicene faith and taught the full divinity of the Holy Spirit.','لە ساڵی ٣٧٠ بوو بە ئەسقوفی قیصەریەی کەپەدۆکیا. فێربوونی باوەڕناسی بە خزمەتی نەخۆشان و هەژاران و ڕێنمایی کۆمەڵە ڕاهیبەکان بەستەوە. لەگەڵ باوکانی دیکەی کەپەدۆکیا داکۆکی لە باوەڕی نیقیە کرد و خوایەتیی تەواوی ڕۆحی پیرۆزی فێر دەکرد.','Fourth-century Cappadocia, amid disputes over the Nicene confession and the divinity of the Son and Holy Spirit.','کەپەدۆکیای سەدەی چوارەم، لە ناو مشتومڕەکانی باوەڕی نیقیە و خوایەتیی کوڕ و ڕۆحی پیرۆزدا.','Trinitarian theology, communal monastic life, and organized Christian charity.','باوەڕناسیی سێیەکێتی، ژیانی ڕاهیبایەتیی کۆمەڵ و ڕێکخستنی خێرخوازیی مەسیحی.','On the Holy Spirit; Ascetical Rules; Letters; Hexaemeron.','دەربارەی ڕۆحی پیرۆز؛ ڕێساکانی ژیانی زاهدانە؛ نامەکان؛ شەش ڕۆژی ئافراندن.','1 January','١ی کانوونی دووەم','Basil became bishop of Caesarea in Cappadocia in 370.','لە ساڵی ٣٧٠ بوو بە ئەسقوفی قیصەریەی کەپەدۆکیا.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('2d7f8b57-2a33-40ad-876e-baf7c4496a34','gregory-theologian','static-saint:gregory-theologian','Saint Gregory the Theologian','پایەپیرۆز گریگۆری باوەڕناس','','the Theologian','','Archbishop of Constantinople','سەرئەسقوفی قسطنطینیە',array['Gregory of Nazianzus','Gregory Nazianzen']::text[],'saint-and-father',2,true,'/icons/gregory-theologian.webp','Saint Gregory the Theologian — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Gregory_of_Nazianzus.jpg','','https://www.oca.org/saints/id/lives/100298','https://www.oca.org/saints/id/lives/100298','c. 329–389/390','c. 329–389/390','Gregory of Nazianzus was a close friend of Basil. His preaching in Constantinople helped restore the Nicene confession there. He briefly presided at the council of 381 before retiring. His sermons, letters, and poetry unite careful teaching about the Trinity with a deeply prayerful voice.','گریگۆری نەزیەنزۆس هاوڕێی نزیکی باسیلیۆس بوو. وتارەکانی لە قسطنطینیە یارمەتیی گەڕاندنەوەی باوەڕی نیقیەیان دا. بۆ ماوەیەکی کورت سەرۆکایەتیی ئەنجومەنی ٣٨١ی کرد. وتار و نامە و شیعرەکانی فێرکردنی وردی سێیەکێتی بە ژیانێکی نوێژئامێز دەبەستنەوە.','The struggle over Arian teaching in the eastern Roman Empire; the council of Constantinople in 381.','ململانێی فێرکردنی ئاریوسی لە ڕۆژهەڵاتی ئیمپراتۆریەتی ڕۆمان و ئەنجومەنی قسطنطینیە لە ٣٨١.','Clarified Trinitarian language and defended Christ''s complete humanity, including a human mind.','زمانی باوەڕناسیی سێیەکێتیی ڕوون کردەوە و داکۆکی لە مرۆڤایەتیی تەواوی مەسیح، لەگەڵ هزری مرۆڤانەی، کرد.','Five Theological Orations (27–31); Letters 101–102; theological poems.','پێنج وتاری باوەڕناسی (٢٧–٣١)؛ نامەکانی ١٠١–١٠٢؛ شیعرە باوەڕناسییەکان.','25 January','٢٥ی کانوونی دووەم','Gregory of Nazianzus was a close friend of Basil.','گریگۆری نەزیەنزۆس هاوڕێی نزیکی باسیلیۆس بوو.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('773cc5e0-64cf-4343-88f3-cdd0e078f6c7','athanasius','static-saint:athanasius','Saint Athanasius the Great','پایەپیرۆز ئەتاناسیۆسی مەزن','','the Great','','Patriarch of Alexandria','پاتریارکی ئەسکەندەریە',array['پایەپیرۆز ئەتاناسیۆسی ئەسکەندەری','Athanasius of Alexandria']::text[],'saint-and-father',3,true,'/icons/athanasius.webp','Saint Athanasius the Great — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Saint-Athanasius-of-Alexandria-icon-Sozopol-Bulgaria-17century.jpg','','https://www.oca.org/saints/lives/2026/05/02/101269-saint-athanasius-the-great-patriarch-of-alexandria','https://www.oca.org/saints/lives/2026/05/02/101269-saint-athanasius-the-great-patriarch-of-alexandria','c. 297–373','c. 297–373','Athanasius attended Nicaea in 325 as a deacon and became bishop of Alexandria in 328. Repeated exiles marked his defense of the Nicene faith. He taught that the Son is truly God and that the Word truly became human for our salvation.','وەک شماس لە ئەنجومەنی نیقیەی ٣٢٥ بەشدار بوو و لە ٣٢٨ بوو بە ئەسقوفی ئەسکەندەریە. داکۆکییەکەی لە باوەڕی نیقیە چەندین جار بووە هۆی دوورخستنەوەی. فێری دەکرد کە کوڕ بەڕاستی خودایە و وشە بۆ ڕزگاریی ئێمە بەڕاستی بوو بە مرۆڤ.','Fourth-century controversy over Arius and the confession that the Son is of one essence with the Father.','مشتومڕی سەدەی چوارەم لەسەر ئاریوس و دانپێدان بەوەی کوڕ هاوجەوهەری باوکە.','Defended the Incarnation and salvation as participation in God''s life by grace, never a change into God''s essence.','داکۆکی لە مرۆڤبوونی وشە و ڕزگاری وەک بەشداربوون لە ژیانی خودا بە نیعمەت کرد، نەک گۆڕان بۆ جەوهەری خودا.','On the Incarnation; Orations against the Arians; Life of Antony; Letters to Serapion.','دەربارەی مرۆڤبوون؛ وتارەکان دژی ئاریوسییەکان؛ ژیانی ئەنتۆنیۆس؛ نامەکان بۆ سەراپیۆن.','2 May; also 18 January with Saint Cyril','٢ی ئایار؛ هەروەها ١٨ی کانوونی دووەم لەگەڵ سیریل','Athanasius attended Nicaea in 325 as a deacon and became bishop of Alexandria in 328.','وەک شماس لە ئەنجومەنی نیقیەی ٣٢٥ بەشدار بوو و لە ٣٢٨ بوو بە ئەسقوفی ئەسکەندەریە.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('83cfa359-8ba1-4212-8bef-22d1b5bec304','ephrem','static-saint:ephrem','Saint Ephrem the Syrian','پایەپیرۆز ئەفرێمی سووریانی','','the Syrian','','Deacon and hymnographer','شماس و سروودنووس',array['پایەپیرۆز ئەفرایمی سووریانی','Ephraim','Ephrem the Syrian']::text[],'saint-and-father',4,true,'/icons/ephrem.webp','Saint Ephrem the Syrian — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Mor_Ephrem_icon.jpg','','https://www.oca.org/saints/lives/2021/01/28/100328-venerable-ephraim-the-syrian','https://www.oca.org/saints/lives/2021/01/28/100328-venerable-ephraim-the-syrian','c. 306–373','c. 306–373','Ephrem was a Syriac-speaking deacon, poet, and teacher. He lived in Nisibis and later Edessa after Nisibis passed to Persian rule in 363. His hymns taught the Christian faith through biblical images. He also served people suffering during famine.','ئەفرێم شماس، شاعیر و مامۆستایەکی سووریانیزمان بوو. لە نیسیبین ژیا و دوای کەوتنی شارەکە ژێر دەسەڵاتی فارس لە ٣٦٣، چوو بۆ ڕوها. سروودەکانی بە وێنەکانی کتێبی پیرۆز باوەڕی مەسیحییان فێر دەکرد؛ هەروەها خزمەتی لێقەوماوانی لە کاتی برسێتیدا کرد.','The Syriac Christian world between Roman and Persian territories in the fourth century.','جیهانی مەسیحیی سووریانی لە نێوان ناوچەکانی ڕۆمان و فارس لە سەدەی چوارەمدا.','Biblical poetry and hymns on the Incarnation, faith, and repentance shaped Syriac Christian worship.','شیعر و سروودەکانی لەسەر مرۆڤبوون، باوەڕ و تۆبە کاریگەرییان لە پەرستشی مەسیحیی سووریانی دانا.','Hymns on the Nativity; Hymns on Paradise; Hymns on Faith.','سروودەکانی لەدایکبوون؛ سروودەکانی بەهەشت؛ سروودەکانی باوەڕ.','28 January','٢٨ی کانوونی دووەم','Ephrem was a Syriac-speaking deacon, poet, and teacher.','ئەفرێم شماس، شاعیر و مامۆستایەکی سووریانیزمان بوو.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('ffccaf3a-1f3c-47fa-8f45-62022c26e339','isaac','static-saint:isaac','Saint Isaac the Syrian','پایەپیرۆز ئیسحاقی سووریانی','','the Syrian','','Bishop of Nineveh and ascetic','ئەسقوفی نەینەوا و زاهد',array['Isaac of Nineveh','Isaac the Syrian']::text[],'saint-and-father',5,true,'/icons/isaac.webp','Saint Isaac the Syrian — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Isaac_of_Nineveh.jpg','','https://www.goarch.org/chapel/saints?contentid=1950','Biography: https://www.goarch.org/chapel/saints?contentid=1950
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('c100fa5f-1702-430a-82e4-8b6c3d0560a7','paisios','static-saint:paisios','Saint Paisios of Mount Athos','پایەپیرۆز پائیسیۆسی ئاتۆس','','of Mount Athos','','Monk of Mount Athos','ڕاهیبی ئاتۆس',array['Paisios the Athonite','Paisius']::text[],'saint-and-father',6,true,'/icons/paisios.webp','Saint Paisios of Mount Athos — Orthodox icon','Russian Orthodox Cathedral of St John the Baptist from Washington DC, United States · CC BY-SA 2.0. Resized for the web; photograph cropped to focus on the icon.','https://commons.wikimedia.org/wiki/File:%D0%98%D0%BA%D0%BE%D0%BD%D0%B0_%D0%9F%D0%B0%D0%B8%D1%81%D0%B8%D1%8F_%D0%A1%D0%B2%D1%8F%D1%82%D0%BE%D0%B3%D0%BE%D1%80%D1%86%D0%B0_%D0%B2_%D0%98%D0%BE%D0%B0%D0%BD%D0%BD%D0%BE-%D0%9F%D1%80%D0%B5%D0%B4%D1%82%D0%B5%D1%87%D0%B5%D0%BD%D1%81%D0%BA%D0%BE%D0%BC_%D1%81%D0%BE%D0%B1%D0%BE%D1%80%D0%B5_%D0%B2_%D0%92%D0%B0%D1%88%D0%B8%D0%BD%D0%B3%D1%82%D0%BE%D0%BD%D0%B5.jpg','https://creativecommons.org/licenses/by-sa/2.0','https://www.oca.org/saints/lives/2026/07/12/100401-venerable-paisios-of-the-holy-mountain','https://www.oca.org/saints/lives/2026/07/12/100401-venerable-paisios-of-the-holy-mountain','25 July 1924–12 July 1994','25 July 1924–12 July 1994','Born in Pharasa in Cappadocia, Paisios grew up in Greece after his family''s displacement. Following military service he entered monastic life and lived on Athos and in Sinai. Many sought his spiritual counsel. He died at Souroti in 1994 and was glorified by the Ecumenical Patriarchate in 2015.','لە فاراسای کەپەدۆکیا لەدایک بوو و دوای ئاوارەبوونی خێزانەکەی لە یۆنان گەورە بوو. دوای خزمەتی سەربازی چووە ژیانی ڕاهیبایەتی و لە ئاتۆس و سینا ژیا. خەڵکێکی زۆر ڕاوێژی ڕۆحییان لێ دەخواست. لە ١٩٩٤ لە سوورۆتی کۆچی دوایی کرد و پاتریارکیەتی جیهانی لە ٢٠١٥ بە پیرۆزی ڕایگەیاند.','Twentieth-century Greek Orthodox monasticism, shaped by displacement, war, and the renewal of Athonite life.','ڕاهیبایەتیی ئۆرتۆدۆکسی یۆنانی لە سەدەی بیستەمدا، لە ناو ئاوارەبوون و جەنگ و نوێبوونەوەی ژیانی ئاتۆسدا.','Pastoral counsel on prayer, humility, discernment, and care for one''s neighbour.','ڕاوێژی شوانایەتی لەسەر نوێژ، خاکەڕایی، جیاکردنەوەی ڕۆحی و چاودێریی نزیکەکان.','Saint Arsenios the Cappadocian; Athonite Fathers and Athonite Matters; Epistles. Spiritual Counsels was compiled by the sisters of Souroti from his teaching.','پایەپیرۆز ئەرسەنیۆسی کەپەدۆکی؛ باوکانی ئاتۆس و بابەتەکانی ئاتۆس؛ نامەکان. ڕاوێژە ڕۆحییەکان لەلایەن خوشکانی سوورۆتییەوە لە فێرکردنەکانی کۆکراوەتەوە.','12 July','١٢ی تەمووز','Born in Pharasa in Cappadocia, Paisios grew up in Greece after his family''s displacement.','لە فاراسای کەپەدۆکیا لەدایک بوو و دوای ئاوارەبوونی خێزانەکەی لە یۆنان گەورە بوو.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('6d3139e7-8c3e-4dc7-82a7-5d650495dbd3','anthony','static-saint:anthony','Saint Anthony the Great','پایەپیرۆز ئەنتۆنیۆسی مەزن','','the Great','','Desert monastic father','باوکی ڕاهیبایەتیی بیابان',array['پایەپیرۆز ئەنتۆنی مەزن','Antony the Great','Anthony of Egypt']::text[],'saint-and-father',7,true,'/icons/anthony.webp','Saint Anthony the Great — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Cretan_Icon_Saint_Anthony_the_Great.jpg','','https://www.oca.org/saints/all-lives/2022/01/17/100216-venerable-and-god-bearing-father-anthony-the-great','https://www.oca.org/saints/all-lives/2022/01/17/100216-venerable-and-god-bearing-father-anthony-the-great','c. 251–356','c. 251–356','Anthony grew up in Egypt. Hearing Christ''s call to the rich man in Matthew 19:21, he distributed his possessions and embraced ascetic life. Other monks sought his guidance in the desert. Athanasius''s Life of Antony made his example known far beyond Egypt.','لە میسر گەورە بوو. کاتێک بانگەوازی مەسیحی بۆ پیاوە دەوڵەمەندەکە لە مەتا ١٩:٢١ بیست، ماڵ و سامانی بەخشی و ژیانی زاهدانەی هەڵبژارد. ڕاهیبەکانی دیکە لە بیابان ڕێنماییان لێ دەخواست. کتێبی ژیانی ئەنتۆنیۆس، نووسینی ئەتاناسیۆس، نموونەکەی لە دەرەوەی میسریش ناساند.','Early Egyptian desert monasticism, during the transition from persecution to imperial recognition of Christianity.','سەرەتای ڕاهیبایەتیی بیابانی میسر، لە گواستنەوە لە چەوساندنەوە بۆ دانپێدانانی ئیمپراتۆری بە مەسیحیەت.','A foundational example of Christian asceticism, spiritual discernment, and persevering prayer.','نموونەیەکی بنەڕەتیی زوهدی مەسیحی، جیاکردنەوەی ڕۆحی و بەردەوامی لە نوێژدا.','His teaching is preserved in Athanasius''s Life of Antony and the Sayings of the Desert Fathers. The Life is by Athanasius, not Anthony.','فێرکردنەکانی لە ژیانی ئەنتۆنیۆس و وتەکانی باوکانی بیابان پارێزراون. ژیاننامەکە نووسینی ئەتاناسیۆسە، نەک ئەنتۆنیۆس.','17 January','١٧ی کانوونی دووەم','Anthony grew up in Egypt.','لە میسر گەورە بوو.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('a0f9ff7c-34dd-42b2-8f60-27f6bcc9d175','maximus','static-saint:maximus','Saint Maximus the Confessor','پایەپیرۆز ماکسیمی دانپێدەر','','the Confessor','','Monk and confessor','ڕاهیب و دانپێدەر',array['Maximos the Confessor']::text[],'saint-and-father',8,true,'/icons/maximus.webp','Saint Maximus the Confessor — Orthodox icon','Tzortzis Phouka · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:Athonite_Fresco_Icon_of_Saint_Maximos_the_Confessor_2.jpg','','https://www.oca.org/saints/lives/2026/01/21/100249-venerable-maximus-the-confessor','https://www.oca.org/saints/lives/2026/01/21/100249-venerable-maximus-the-confessor','c. 580–662','c. 580–662','Maximus became a monk and a leading defender of Christ''s complete humanity. He opposed the claim that Christ had only one will. Condemned, mutilated, and exiled, he died in 662. The Sixth Ecumenical Council later affirmed the teaching that Christ has both a divine and a human will.','بوو بە ڕاهیب و داکۆکیکارێکی گرنگی مرۆڤایەتیی تەواوی مەسیح. دژی ئەو بانگەشەیە وەستایەوە کە مەسیح تەنها یەک ویستی هەیە. سزا درا، ئەندامی بڕدرا و دوورخرایەوە؛ لە ٦٦٢ کۆچی دوایی کرد. ئەنجومەنی شەشەم دواتر پشتڕاستی کردەوە کە مەسیح هەم ویستی خودایی و هەم ویستی مرۆڤانەی هەیە.','Seventh-century disputes over Christ''s wills and energies, resolved at Constantinople in 680–681.','مشتومڕەکانی سەدەی حەوتەم لەسەر ویست و کردەکانی مەسیح، کە لە قسطنطینیەی ٦٨٠–٦٨١ یەکلایی کرانەوە.','Christology, spiritual interpretation of Scripture, love, and the transformation of creation in Christ.','مەسیحناسی، لێکدانەوەی ڕۆحیی کتێبی پیرۆز، خۆشەویستی و گۆڕانی ئافراندن لە مەسیحدا.','Four Hundred Texts on Love; Ambigua; Mystagogy; Questions to Thalassius.','چوارسەد دەق لەسەر خۆشەویستی؛ ئەمبیگوا؛ میستاگۆگیا؛ پرسیارەکان بۆ تەلاسیۆس.','21 January; also 13 August','٢١ی کانوونی دووەم؛ هەروەها ١٣ی ئاب','Maximus became a monk and a leading defender of Christ''s complete humanity.','بوو بە ڕاهیب و داکۆکیکارێکی گرنگی مرۆڤایەتیی تەواوی مەسیح.') on conflict do nothing;
insert into public.authors (id,slug,legacy_key,name_en,name_ckb,name_kmr,title_en,title_ckb,position_en,position_ckb,aliases,kind,sort_order,published,icon_url,icon_alt,icon_credit,icon_source,icon_license_url,source_url,source_reference,life_dates_en,life_dates_ckb,biography_en,biography_ckb,history_en,history_ckb,contributions_en,contributions_ckb,writings_intro_en,writings_intro_ckb,feast_en,feast_ckb,summary_en,summary_ckb) values ('d00ac04b-63cf-4116-8ed6-eaea74165605','gregory-nyssa','static-saint:gregory-nyssa','Saint Gregory of Nyssa','پایەپیرۆز گریگۆری نیسا','','of Nyssa','','Bishop of Nyssa','ئەسقوفی نیسا',array['Gregory of Nyssa']::text[],'saint-and-father',9,true,'/icons/gregory-nyssa.webp','Saint Gregory of Nyssa — Orthodox icon','Unknown iconographer · Public domain. Resized for the web.','https://commons.wikimedia.org/wiki/File:St._Gregory_of_Nyssa.jpg','','https://www.oca.org/saints/lives/2024/01/10/100140-saint-gregory-bishop-of-nyssa','https://www.oca.org/saints/lives/2024/01/10/100140-saint-gregory-bishop-of-nyssa','c. 335–after 394','c. 335–after 394','Gregory, the younger brother of Basil, became bishop of Nyssa in 372. After exile during the Arian controversy, he returned to his see and participated in the council of 381. His writings explore Scripture, the human person, and the soul''s continuing growth toward God.','برای بچووکترِ باسیلیۆس بوو و لە ٣٧٢ بوو بە ئەسقوفی نیسا. دوای دوورخستنەوەی لە کاتی مشتومڕی ئاریوسی، گەڕایەوە بۆ کورسییەکەی و لە ئەنجومەنی ٣٨١ بەشدار بوو. نووسینەکانی کتێبی پیرۆز، کەسی مرۆڤ و گەشەی بەردەوامی گیان بەرەو خودا دەکۆڵنەوە.','A Cappadocian Father in the fourth-century defense of the Nicene faith; his exact death year is not established.','یەکێک لە باوکانی کەپەدۆکیا لە داکۆکیکردن لە باوەڕی نیقیەی سەدەی چوارەمدا؛ ساڵی وردی مردنی بە دڵنیایی دیار نییە.','Trinitarian theology, biblical interpretation, and the dignity of humanity made in God''s image.','باوەڕناسیی سێیەکێتی، لێکدانەوەی کتێبی پیرۆز و شکۆی مرۆڤ کە لەسەر وێنەی خودا ئافرێنراوە.','The Life of Moses; The Great Catechism; On the Making of Man; On the Soul and the Resurrection.','ژیانی موسا؛ فێرکاریی مەزن؛ دەربارەی ئافراندنی مرۆڤ؛ دەربارەی گیان و هەستانەوە.','10 January','١٠ی کانوونی دووەم','Gregory, the younger brother of Basil, became bishop of Nyssa in 372.','برای بچووکترِ باسیلیۆس بوو و لە ٣٧٢ بوو بە ئەسقوفی نیسا.') on conflict do nothing;
insert into public.authors(slug,legacy_key,name_en,name_ckb,name_kmr,published,kind)
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select 'c1400e12-328c-4559-8e85-c322da42bdad',(select id from public.authors where legacy_key='static-saint:chrysostom' limit 1),'Saint John Chrysostom','Would you do honor to Christ''s body? Neglect Him not when naked','دەتەوێت ڕێز لە جەستەی مەسیح بگریت؟ کاتێک ڕووتە پشتگوێی مەخە.','','Homilies on Matthew · Homily 50, §4','https://www.newadvent.org/fathers/200150.htm','Patristic teaching',true,'static-quote:chrysostom' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:chrysostom' limit 1) and (position(public.editorial_name_key('دەتەوێت ڕێز لە جەستەی مەسیح بگریت؟ کاتێک ڕووتە پشتگوێی مەخە.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('Would you do honor to Christ''s body? Neglect Him not when naked') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select '07b2786f-d301-4c7e-8d5a-d4291dd680a9',(select id from public.authors where legacy_key='static-saint:basil' limit 1),'Saint Basil the Great','Through the Holy Spirit comes our restoration to paradise','لە ڕێگەی ڕۆحی پیرۆزەوە گەڕانەوەمان بۆ بەهەشت دێت.','','On the Holy Spirit · Chapter 15, §36','https://www.newadvent.org/fathers/3203.htm','Patristic teaching',true,'static-quote:basil' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:basil' limit 1) and (position(public.editorial_name_key('لە ڕێگەی ڕۆحی پیرۆزەوە گەڕانەوەمان بۆ بەهەشت دێت.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('Through the Holy Spirit comes our restoration to paradise') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select 'cabef251-edda-4bf8-8e62-dfea566a1591',(select id from public.authors where legacy_key='static-saint:gregory-theologian' limit 1),'Saint Gregory the Theologian','For that which He has not assumed He has not healed','چونکە ئەوەی وەرینەگرتووە، چاکیشی نەکردووەتەوە.','','First Letter to Cledonius · Letter 101, against Apollinarius','https://www.newadvent.org/fathers/3103a.htm','Patristic teaching',true,'static-quote:gregory-theologian' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:gregory-theologian' limit 1) and (position(public.editorial_name_key('چونکە ئەوەی وەرینەگرتووە، چاکیشی نەکردووەتەوە.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('For that which He has not assumed He has not healed') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select 'e93b2e9e-9315-45a1-8f0b-b5b2685b98ab',(select id from public.authors where legacy_key='static-saint:athanasius' limit 1),'Saint Athanasius the Great','For He was made man that we might be made God','چونکە ئەو بوو بە مرۆڤ، تاکو ئێمە بە خودا بین (بە نیعمەت).','','On the Incarnation · §54.3 — deification by grace','https://www.newadvent.org/fathers/2802.htm','Patristic teaching',true,'static-quote:athanasius' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:athanasius' limit 1) and (position(public.editorial_name_key('چونکە ئەو بوو بە مرۆڤ، تاکو ئێمە بە خودا بین (بە نیعمەت).') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('For He was made man that we might be made God') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select '0ad3237e-3fdf-4a47-8cbe-3cd24999f8a7',(select id from public.authors where legacy_key='static-saint:ephrem' limit 1),'Saint Ephrem the Syrian','For the Virgin this day brought forth Immanuel in Bethlehem.','چونکە پاکیزە ئەمڕۆ لە بەیت‌لەحم عیمانوێلی لەدایک بوو.','','Hymns on the Nativity · Hymn 1, opening stanza','https://www.newadvent.org/fathers/3703.htm','Patristic teaching',true,'static-quote:ephrem' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:ephrem' limit 1) and (position(public.editorial_name_key('چونکە پاکیزە ئەمڕۆ لە بەیت‌لەحم عیمانوێلی لەدایک بوو.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('For the Virgin this day brought forth Immanuel in Bethlehem.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select '00b997b7-58a5-4b2d-8612-2bab49d61cac',(select id from public.authors where legacy_key='static-saint:isaac' limit 1),'Saint Isaac the Syrian','If you are not a peacemaker, at least do not be a troublemaker.','ئەگەر ئاشتیخواز نیت، لانیکەم ئاژاوەگێڕ مەبە.','','The Ascetical Homilies · Homily 51 · Holy Transfiguration Monastery, 1984, pp. 243–248 (excerpt p. 247)','https://jbburnett.com/resources/Isaac-the-Syrian-Homily-51.pdf','Patristic teaching',true,'static-quote:isaac' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:isaac' limit 1) and (position(public.editorial_name_key('ئەگەر ئاشتیخواز نیت، لانیکەم ئاژاوەگێڕ مەبە.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('If you are not a peacemaker, at least do not be a troublemaker.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select '2bfb5f9f-8fc8-4b0e-8e44-e38f045a69b4',(select id from public.authors where legacy_key='static-saint:paisios' limit 1),'Saint Paisios of Mount Athos','Only when man is reconciled with God can inward and outward peace come.','تەنها کاتێک مرۆڤ لەگەڵ خودا ئاشت دەبێتەوە، ئاشتیی ناوەوە و دەرەوە دەتوانێت بێت.','','Spiritual Counsels II: Spiritual Awakening · p. 395 · reproduced in Holy Cross parish bulletin, 6 July 2025','https://www.holycrosswilliamsport.org/files/Holy-Cross-2025/Bulletin-July-6-2025-Ven-Sisoes.pdf','Patristic teaching',true,'static-quote:paisios' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:paisios' limit 1) and (position(public.editorial_name_key('تەنها کاتێک مرۆڤ لەگەڵ خودا ئاشت دەبێتەوە، ئاشتیی ناوەوە و دەرەوە دەتوانێت بێت.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('Only when man is reconciled with God can inward and outward peace come.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select 'a7c6a625-28d2-471f-876b-7711d66141e6',(select id from public.authors where legacy_key='static-saint:anthony' limit 1),'Saint Anthony the Great','Wherefore, children, let us hold fast our discipline, and let us not be careless.','کەواتە، منداڵەکانم، با بە ڕاهێنانە ڕۆحییەکەمانەوە پابەند بین و کەمتەرخەم نەبین.','','Athanasius, Life of Antony · §19 · Anthony''s teaching as recorded by Athanasius','https://www.newadvent.org/fathers/2811.htm','Patristic teaching',true,'static-quote:anthony' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:anthony' limit 1) and (position(public.editorial_name_key('کەواتە، منداڵەکانم، با بە ڕاهێنانە ڕۆحییەکەمانەوە پابەند بین و کەمتەرخەم نەبین.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('Wherefore, children, let us hold fast our discipline, and let us not be careless.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select 'a7065f2d-d05e-444d-8bcb-887ba69bade8',(select id from public.authors where legacy_key='static-saint:maximus' limit 1),'Saint Maximus the Confessor','Love is a holy state of the soul, disposing it to value knowledge of God above all created things.','خۆشەویستی دۆخێکی پیرۆزی گیانە، کە وایدەکات ناسینی خودا لە هەموو شتە ئافرێنراوەکان بەهادارتر بزانێت.','','Four Hundred Texts on Love · First Century, §1 · Philokalia, vol. II','https://www.stasinos.org/Arthra/Philokalia-St%20Maximos%20The%20Confessor%20on%20Love.aspx','Patristic teaching',true,'static-quote:maximus' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:maximus' limit 1) and (position(public.editorial_name_key('خۆشەویستی دۆخێکی پیرۆزی گیانە، کە وایدەکات ناسینی خودا لە هەموو شتە ئافرێنراوەکان بەهادارتر بزانێت.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('Love is a holy state of the soul, disposing it to value knowledge of God above all created things.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.quotes(id,author_id,father,text_en,text_ckb,text_kmr,reference,source_url,topic,published,legacy_key) select '85b02005-4e2f-4ccf-8140-0312a7210745',(select id from public.authors where legacy_key='static-saint:gregory-nyssa' limit 1),'Saint Gregory of Nyssa','We say nothing different from that which Scripture says.','هیچ شتێکی جیاواز لەوەی کتێبی پیرۆز دەیڵێت، ناڵێین.','','On the Holy Spirit, Against the Macedonians · Opening argument · paragraph beginning ‘We say nothing different’','https://www.newadvent.org/fathers/2903.htm','Patristic teaching',true,'static-quote:gregory-nyssa' where not exists(select 1 from public.quotes q where q.author_id=(select id from public.authors where legacy_key='static-saint:gregory-nyssa' limit 1) and (position(public.editorial_name_key('هیچ شتێکی جیاواز لەوەی کتێبی پیرۆز دەیڵێت، ناڵێین.') in public.editorial_name_key(q.text_ckb))>0 or position(public.editorial_name_key('We say nothing different from that which Scripture says.') in public.editorial_name_key(coalesce(q.text_en,q.text_kmr)))>0)) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,bible_references,source_url,reference,published,sort_order) values ('c07ee532-800d-41a0-8c59-1ec1357ebd04','holy-trinity','static-lesson:0','The Holy Trinity','سێیەکێتیی پیرۆز','One God in three divine Persons: Father, Son, and Holy Spirit. The Persons share one divine nature; they are not three gods.','یەک خودا لە سێ کەسی خوداییدا: باوک، کوڕ و ڕۆحی پیرۆز. هەر سێ کەسەکە یەک سروشتی خوداییان هەیە؛ سێ خودا نین.','One God in three divine Persons: Father, Son, and Holy Spirit. The Persons share one divine nature; they are not three gods.','یەک خودا لە سێ کەسی خوداییدا: باوک، کوڕ و ڕۆحی پیرۆز. هەر سێ کەسەکە یەک سروشتی خوداییان هەیە؛ سێ خودا نین.','Matthew 28:19','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-holy-trinity/the-doctrine-of-the-holy-trinity','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/the-holy-trinity/the-doctrine-of-the-holy-trinity',true,0) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,bible_references,source_url,reference,published,sort_order) values ('5c6b4518-810f-40c5-8745-692d6d915b3e','incarnation','static-lesson:1','The Incarnation','مرۆڤبوونی وشە','The eternal Son truly became human for our salvation, remaining truly God. Jesus Christ is one Person in two natures.','کوڕی هەتاهەتایی بۆ ڕزگاریی ئێمە بەڕاستی بوو بە مرۆڤ، لە کاتێکدا بەڕاستی خودا مایەوە. عیسای مەسیح یەک کەسە لە دوو سروشتدا.','The eternal Son truly became human for our salvation, remaining truly God. Jesus Christ is one Person in two natures.','کوڕی هەتاهەتایی بۆ ڕزگاریی ئێمە بەڕاستی بوو بە مرۆڤ، لە کاتێکدا بەڕاستی خودا مایەوە. عیسای مەسیح یەک کەسە لە دوو سروشتدا.','John 1:14','https://www.newadvent.org/fathers/2802.htm','https://www.newadvent.org/fathers/2802.htm',true,1) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,bible_references,source_url,reference,published,sort_order) values ('9fc86863-be17-475b-85d6-827c62684c2f','holy-eucharist','static-lesson:2','The Holy Eucharist','قوربانیی پیرۆز','In the Divine Liturgy the faithful receive Christ''s true Body and Blood. The Eucharist stands at the centre of the Church''s life.','لە لیتورژیای خوداییدا باوەڕداران جەستە و خوێنی ڕاستەقینەی مەسیح وەردەگرن. قوربانیی پیرۆز لە ناوەندی ژیانی کڵێسادایە.','In the Divine Liturgy the faithful receive Christ''s true Body and Blood. The Eucharist stands at the centre of the Church''s life.','لە لیتورژیای خوداییدا باوەڕداران جەستە و خوێنی ڕاستەقینەی مەسیح وەردەگرن. قوربانیی پیرۆز لە ناوەندی ژیانی کڵێسادایە.','1 Corinthians 10:16–17','https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-sacraments/holy-eucharist','https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-sacraments/holy-eucharist',true,2) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,bible_references,source_url,reference,published,sort_order) values ('6804db52-b3a9-4d4f-8466-bfd9205bb330','prayer-in-christ','static-lesson:3','Prayer and life in Christ','نوێژ و ژیان لە مەسیحدا','Christian prayer draws us to the Father, through the Son, in the Holy Spirit. Repentance, mercy, and love of our neighbour belong with prayer.','نوێژی مەسیحی لە ڕێگەی کوڕەوە و بە ڕۆحی پیرۆز ئێمە بەرەو باوک دەبات. تۆبە و بەزەیی و خۆشەویستیی نزیکەکان لەگەڵ نوێژدان.','Christian prayer draws us to the Father, through the Son, in the Holy Spirit. Repentance, mercy, and love of our neighbour belong with prayer.','نوێژی مەسیحی لە ڕێگەی کوڕەوە و بە ڕۆحی پیرۆز ئێمە بەرەو باوک دەبات. تۆبە و بەزەیی و خۆشەویستیی نزیکەکان لەگەڵ نوێژدان.','Romans 8:15–16; Matthew 6:5–15','https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-daily-cycles-of-prayer/prayer','https://www.oca.org/orthodoxy/the-orthodox-faith/worship/the-daily-cycles-of-prayer/prayer',true,3) on conflict do nothing;
