insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('d043a9b6-9006-4281-893a-46db931b3687','council-325','static-council:325','council','325','Nicaea I','نیقیەی یەکەم','The Son is truly God, of one essence with the Father.','کوڕ بەڕاستی خودایە و هاوجەوهەری باوکە.','The Son is truly God, of one essence with the Father.','کوڕ بەڕاستی خودایە و هاوجەوهەری باوکە.','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/sources-of-christian-doctrine/the-councils',true,0) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('7f74b91f-8cdd-4012-86f1-09ace9efc3d3','council-381','static-council:381','council','381','Constantinople I','قسطنطینیەی یەکەم','Confessed the Holy Spirit''s divinity; completed the Creed.','خوایەتیی ڕۆحی پیرۆزی ڕاگەیاند؛ باوەڕنامەکەی تەواو کرد.','Confessed the Holy Spirit''s divinity; completed the Creed.','خوایەتیی ڕۆحی پیرۆزی ڕاگەیاند؛ باوەڕنامەکەی تەواو کرد.','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/sources-of-christian-doctrine/the-councils',true,1) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('dbf56a3a-f0f3-490d-87af-b556448c154d','council-431','static-council:431','council','431','Ephesus','ئەفەسۆس','Christ is one Person; Mary is Theotokos, Mother of God.','مەسیح یەک کەسە؛ مەریەم تێئۆتۆکۆسە، دایکی خودا.','Christ is one Person; Mary is Theotokos, Mother of God.','مەسیح یەک کەسە؛ مەریەم تێئۆتۆکۆسە، دایکی خودا.','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/sources-of-christian-doctrine/the-councils',true,2) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('81bd6a31-093e-467e-8f9d-75538f53299c','council-451','static-council:451','council','451','Chalcedon','خەلقیدۆن','One and the same Christ in two natures, divine and human, without confusion or division.','هەمان یەک مەسیح لە دوو سروشتدا، خودایی و مرۆڤانە، بەبێ تێکەڵبوون یان دابەشبوون.','One and the same Christ in two natures, divine and human, without confusion or division.','هەمان یەک مەسیح لە دوو سروشتدا، خودایی و مرۆڤانە، بەبێ تێکەڵبوون یان دابەشبوون.','https://www.oca.org/orthodoxy/the-orthodox-faith/church-history/fifth-century/the-fourth-ecumenical-council',true,3) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('720064d6-65b3-4f54-8583-a43e87c4c62f','council-553','static-council:553','council','553','Constantinople II','قسطنطینیەی دووەم','Reaffirmed the one divine Person of the incarnate Son.','یەک کەسی خودایی کوڕی مرۆڤبووی پشتڕاست کردەوە.','Reaffirmed the one divine Person of the incarnate Son.','یەک کەسی خودایی کوڕی مرۆڤبووی پشتڕاست کردەوە.','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/sources-of-christian-doctrine/the-councils',true,4) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('4da02f8d-6bed-43b6-8bd7-c6e7e6369521','council-680-681','static-council:680–681','council','680–681','Constantinople III','قسطنطینیەی سێیەم','Christ has divine and human wills and energies.','مەسیح ویست و کردەی خودایی و مرۆڤانەی هەیە.','Christ has divine and human wills and energies.','مەسیح ویست و کردەی خودایی و مرۆڤانەی هەیە.','https://www.oca.org/orthodoxy/the-orthodox-faith/doctrine-scripture/sources-of-christian-doctrine/the-councils',true,5) on conflict do nothing;
insert into public.doctrines (id,slug,legacy_key,category,council_year,title_en,title_ckb,body_en,body_ckb,subtitle_en,subtitle_ckb,source_url,published,sort_order) values ('b60819e2-ea99-4ec6-80d3-e473451633dd','council-787','static-council:787','council','787','Nicaea II','نیقیەی دووەم','Honour given to an icon passes to its prototype; worship belongs to God alone.','ڕێزی دراو بە ئایکۆن دەگاتە کەسی وێنەکە؛ پەرستش تەنها بۆ خودایە.','Honour given to an icon passes to its prototype; worship belongs to God alone.','ڕێزی دراو بە ئایکۆن دەگاتە کەسی وێنەکە؛ پەرستش تەنها بۆ خودایە.','https://www.oca.org/reflections/misc-authors/fathers-seventh-ecumenical-council-relationship-image-person-redemptive-work-sacred-space',true,6) on conflict do nothing;
