insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('05e365aa-bc75-46cb-8c15-4e0cbc7de4f3','ui.prayerTranslationNote','ui','The Kurdish texts are working site translations, not officially approved liturgical translations. English renderings are provided for comparison. A fluent Orthodox editor should review them. Short morning and night prayers are excerpts, not complete daily prayer rules.','تێبینی: دەقە سەرەتاییەکان وەرگێڕانی کاریی ئەم ماڵپەڕەن لە نوێژە نەریتییەکان، نەک وەرگێڕانی فەرمیی کڵێسا. پێویستیان بە پێداچوونەوەی زمانەوانی و کڵێسایی هەیە. نوێژە کورتەکان جێگەی ڕێوڕەسمی تەواوی بەیانی یان شەو ناگرنەوە.','Nîşe: Nivîsên destpêkê wergerên xebatê yên vê malperê ji duayên kevneşopî ne, ne wergerên fermî yên Dêrê. Pêdiviya wan bi kontrola zimanî û dêrî heye. Duayên kurt cihê rêza tam a sibehê an şevê nagirin.','text',true) on conflict do nothing;
