insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('5dfda192-78eb-4f97-813d-aa071bc5de2f','ui.intro','ui','Discover the Eastern Orthodox Christian faith in Sorani and Kurmanji, with English available for comparison.','دەرگایەک بۆ ناسینی باوەڕی مەسیحیی ئۆرتۆدۆکس؛ بە کوردیی سۆرانی و کورمانجی.','Deriyek ji bo naskirina baweriya Xiristiyanî ya Ortodoks; bi Soranî û Kurmancî.','text',true) on conflict do nothing;
