insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('c2e3c2ba-78cf-4aa9-88a6-dec2ea3807e1','ui.journey','ui','Begin with understanding','بە ناسین دەست پێ بکە','Bi naskirinê dest pê bike','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('2454f57a-d2ac-4aa0-824b-53f8084684b9','ui.journeyBody','ui','Read Scripture, learn from the Church Fathers, and explore your questions in the light of Orthodox tradition.','کتێبی پیرۆز بخوێنەوە، لە باوکانی کڵێسا فێر ببە و پرسیارەکانت لە ڕووناکیی نەریتی ئۆرتۆدۆکسدا بپرسە.','Pirtûka Pîroz bixwîne, ji Bavên Dêrê hîn bibe û pirsên xwe di ronahiya kevneşopiya Ortodoks de bipirse.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('d35db329-c6e3-4ce6-8812-73ca15c50d38','ui.fathersDesc','ui','Church Fathers’ quotations with authors, references and source links.','وتەکانی باوکانی کڵێسا، لەگەڵ ناوی نووسەر و سەرچاوە.','Gotinên Bavên Dêrê, bi navê nivîskar û çavkaniyê.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('b5c65bd8-9063-44b8-832a-8ca364e6714f','ui.aiDesc','ui','Ask about the faith and read answers selected from approved Orthodox sources.','پرسیارەکانت بپرسە؛ وەڵامەکان لەسەر بنەمای سەرچاوە پەسەندکراوەکانن.','Pirsên xwe bipirse; bersiv li ser çavkaniyên pejirandî ava dibin.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('81813f79-3abe-4da4-840b-3a0d5f328852','ui.explore','ui','Explore','بیکەرەوە','Veke','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('14cb9490-a29c-4c27-85b1-80eea097fe57','ui.principle','ui','Read. Understand. Live.','خوێندنەوە، تێگەیشتن، ژیان.','Bixwîne, fêm bike, bijî.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('ca6b5c55-ef47-4689-831c-8f60b1f99b4c','ui.principleBody','ui','This platform is for learning. For spiritual guidance and life in the Church, speak with an Orthodox priest.','ئەم پلاتفۆرمە بۆ فێربوونە. بۆ ڕێنماییی ڕۆحی و ژیانی کڵێسا، پەیوەندی بە قەشەیەکی ئۆرتۆدۆکسەوە بکە.','Ev platform ji bo hînbûnê ye. Ji bo rêberiya giyanî û jiyana dêrê bi kahînekî Ortodoks re biaxive.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('24473e44-9321-474e-8fd2-8ac99719824d','ui.footer','ui','A place to learn about the Orthodox faith in the Kurdish language.','شوێنێک بۆ فێربوون و ناسینی باوەڕی ئۆرتۆدۆکس بە زمانی کوردی.','Cihek ji bo hînbûn û naskirina baweriya Ortodoks bi zimanê Kurdî.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('94a33b9d-8608-4ce1-80b8-9950ab610714','ui.sources','ui','Sources','سەرچاوەکان','Çavkanî','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('e3d7e081-3ecd-47dc-87c3-abcd49713ee1','ui.sourcePolicy','ui','Only approved Orthodox source passages are used for answers. When the available evidence is insufficient, the assistant declines to answer.','تەنها سەرچاوە پەسەندکراوە ئۆرتۆدۆکسەکان بۆ وەڵامەکان بەکاردێن. ئەگەر بەڵگەی پێویست نەبێت، وەڵام نادرێتەوە.','Tenê çavkaniyên Ortodoks ên pejirandî ji bo bersivan tên bikaranîn. Dema delîl têr nebin, bersiv nayê dayîn.','text',true) on conflict do nothing;
