insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('e93ccfc1-7088-49fd-8360-b9fa67da1543','ui.bibleNotice','ui','These recognized Kurdish translations are read at their providers’ websites. They are not Orthodox-specific editions. Orthodox reading of Scripture belongs within the living tradition of the Church.','دەقی وەرگێڕانەکان لە سەرچاوە ناسراوەکانیان دەخوێنرێتەوە. ئەمانە وەرگێڕانی تایبەتی ئۆرتۆدۆکس نین؛ خوێندنەوەی ئۆرتۆدۆکس لە چوارچێوەی نەریتی کڵێسادایە.','Werger li malperên çavkaniyên naskirî tên xwendin. Ev ne wergerên taybet ên Ortodoks in; xwendina Ortodoks di çarçoveya kevneşopiya Dêrê de ye.','text',true) on conflict do nothing;
