insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('f048cb75-15e0-439b-8362-63c074ecad39','home.aboutText','home','This educational website introduces the Eastern Orthodox faith to Kurdish readers. It brings Scripture, the lives of the saints, prayers, and Christian teaching together in one place.','ئەم ماڵپەڕە سەرچاوەیەکی فێرکارییە بۆ ناساندنی باوەڕی ئۆرتۆدۆکسی ڕۆژهەڵات بە خوێنەرانی کورد. کتێبی پیرۆز، ژیانی پایەپیرۆزان، نوێژ و فێرکاری لە یەک شوێندا کۆدەکاتەوە.','This educational website introduces the Eastern Orthodox faith to Kurdish readers. It brings Scripture, the lives of the saints, prayers, and Christian teaching together in one place.','text',true) on conflict do nothing;
insert into public.content_blocks (id,key,section,text_en,text_ckb,text_kmr,value_type,published) values ('8c3a6d3c-4236-4187-83b7-42ec9df2186c','home.aboutPolicy','home','Our reference points are Holy Scripture, the Church Fathers, and reliable Orthodox publications. Editorial translations are identified. For personal pastoral guidance, speak with an Orthodox priest.','ناوەڕۆکەکان پشت بە کتێبی پیرۆز، باوکانی کڵێسا و سەرچاوە ئۆرتۆدۆکسییە ناسراوەکان دەبەستن. دەقە وەرگێڕدراوەکان دەستنیشان دەکرێن؛ بۆ ڕێنماییی شوانایەتی پەیوەندی بە قەشەیەکی ئۆرتۆدۆکسەوە بکە.','Our reference points are Holy Scripture, the Church Fathers, and reliable Orthodox publications. Editorial translations are identified. For personal pastoral guidance, speak with an Orthodox priest.','text',true) on conflict do nothing;
