insert into public.bible_editions (id,title_en,title_ckb,title_kmr,description_en,description_ckb,description_kmr,published) values ('ckb_bib','سۆرانی · Open Kurdi Sorani Standard','سۆرانی · وەشانی ستاندەری کراوە','Soranî · Wergera standard a vekirî','This Sorani edition contains 66 books. The additional books of the Orthodox canon are not included in this translation.','ئەم وەشانە سۆرانییە ٦٦ پەڕتووک لەخۆ دەگرێت. پەڕتووکە زیادەکانی کانونی ئۆرتۆدۆکسی لەم وەرگێڕانەدا نین.','Ev wergera Soranî 66 pirtûkan dihewîne. Pirtûkên zêde yên kanona Ortodoks di vê wergerê de nînin.',true) on conflict do nothing;
insert into public.bible_editions (id,title_en,title_ckb,title_kmr,description_en,description_ckb,description_kmr,published) values ('eng_webu','English · World English Bible Updated','English · World English Bible Updated','English · World English Bible Updated','The English edition includes deuterocanonical and additional books. Its book order and Psalm numbering follow this translation.','وەشانە ئینگلیزییەکە پەڕتووکی زیادە لەخۆ دەگرێت. ڕیزبەندی پەڕتووک و ژمارەکانی زەبوور بەپێی ئەم وەرگێڕانەن.','Wergera Îngilîzî pirtûkên zêde jî dihewîne. Rêza pirtûkan û hejmarên Zebûrê li gorî vê wergerê ne.',true) on conflict do nothing;
